import json
import os
import random
import time

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError


def _pick():
    """The models are the ones this simulator hosts: in-browser models on Nano, the Mesh model pool on a Mesh. Ask it, never hard-code a vendor id."""
    ms = [m for m in boto3.client("bedrock").list_foundation_models()["modelSummaries"] if m["modelId"].startswith("vyomi.")]
    chat = [m["modelId"] for m in ms if "EMBEDDING" not in m["outputModalities"]]
    emb = [m["modelId"] for m in ms if "EMBEDDING" in m["outputModalities"]]
    return chat[0], emb[0]


CHAT_MODEL, EMBED_MODEL = _pick()
# One attempt per boto3 call: this module owns the retry policy so the learner can see and test it.
_rt = boto3.client("bedrock-runtime", config=Config(retries={"total_max_attempts": 1}, read_timeout=60))

RETRYABLE = {"ThrottlingException", "ServiceUnavailableException", "ModelTimeoutException", "TooManyRequestsException", "InternalServerException"}
MAX_ATTEMPTS = 4


class ModelUnavailable(RuntimeError):
    """The model kept failing after every retry: surface it, never loop forever."""


class BudgetExceeded(RuntimeError):
    """The spend limit for this layer is used up: refuse the call before it is made."""


# Notional price per 1,000 tokens. The simulator's models are free; the numbers only make the meter and the limit tangible.
PRICE_PER_1K = {"input": 0.003, "output": 0.015, "embed": 0.0001}


class Budget:
    def __init__(self, limit_usd):
        self.limit, self.spent, self.calls, self.tokens = float(limit_usd), 0.0, 0, {"input": 0, "output": 0}

    def check(self):
        if self.spent >= self.limit:
            raise BudgetExceeded("budget of $%.4f used up after %d calls" % (self.limit, self.calls))

    def charge(self, kind, tokens_in=0, tokens_out=0):
        self.calls += 1
        self.tokens["input"] += tokens_in
        self.tokens["output"] += tokens_out
        self.spent += tokens_in / 1000 * PRICE_PER_1K["embed" if kind == "embed" else "input"] + tokens_out / 1000 * PRICE_PER_1K["output"]


BUDGET = Budget(os.environ.get("VY_BUDGET_USD", "1.00"))


def _call(fn):
    """Retry throttling and transient errors with exponential backoff and jitter; anything else (validation, access denied) fails at once."""
    BUDGET.check()
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            return fn()
        except ClientError as e:
            code = e.response["Error"]["Code"]
            if code not in RETRYABLE:
                raise
            if attempt == MAX_ATTEMPTS:
                raise ModelUnavailable("%s after %d attempts" % (code, attempt)) from e
            time.sleep(0.05 * 2 ** attempt + random.random() * 0.05)


def _text(resp):
    return "".join(b.get("text", "") for b in resp["output"]["message"]["content"])


def chat(prompt):
    r = _call(lambda: _rt.converse(modelId=CHAT_MODEL, messages=[{"role": "user", "content": [{"text": prompt}]}], inferenceConfig={"maxTokens": 200}))
    BUDGET.charge("chat", r["usage"]["inputTokens"], r["usage"]["outputTokens"])
    return _text(r)


def chat_with_tools(prompt, tools):
    r = _call(lambda: _rt.converse(modelId=CHAT_MODEL, messages=[{"role": "user", "content": [{"text": prompt}]}], toolConfig={"tools": tools}))
    BUDGET.charge("chat", r["usage"]["inputTokens"], r["usage"]["outputTokens"])
    tool = next((b["toolUse"] for b in r["output"]["message"]["content"] if "toolUse" in b), None)
    return {"stop_reason": r["stopReason"], "tool_use": tool, "text": _text(r)}


def embed(text):
    r = _call(lambda: _rt.invoke_model(modelId=EMBED_MODEL, body=json.dumps({"inputText": text})))
    BUDGET.charge("embed", len(text.split()))
    return json.loads(r["body"].read())["embedding"]

"""Failure injection for the failure labs: make the next N calls to an operation fail the way the real service does."""
import json

from botocore.awsrequest import AWSResponse


class _Raw:
    def __init__(self, body):
        self._b = body

    def stream(self, *a, **k):
        yield self._b

    def read(self, *a, **k):
        return self._b


def inject(client, operation, times, status=429, code="ThrottlingException", message="Too many requests"):
    """Fail the next `times` calls of `operation` (e.g. "Converse") on `client`. Returns a counter dict {'left','seen'}; call .remove() to stop."""
    service = client.meta.service_model.endpoint_prefix
    event = "before-send.%s.%s" % (client.meta.service_model.service_id.hyphenize(), operation)
    state = {"left": times, "seen": 0}

    def handler(request, **kw):
        state["seen"] += 1
        if state["left"] > 0:
            state["left"] -= 1
            body = json.dumps({"__type": code, "message": message}).encode()
            return AWSResponse(request.url, status, {"x-amzn-ErrorType": code, "content-type": "application/json"}, _Raw(body))

    client.meta.events.register(event, handler)
    state["remove"] = lambda: client.meta.events.unregister(event, handler)
    return state

"""Least-privilege helper for the IAM Enforce labs: make a principal with an inline policy, switch the simulator to Enforce, and read the audit log."""
import atexit
import json
import os
import urllib.request

import boto3

EP = os.environ["AWS_ENDPOINT_URL"]
ACCOUNT = "123456789012"


def _admin(method, path, body=None):
    req = urllib.request.Request(EP + path, method=method, data=json.dumps(body).encode() if body is not None else None,
                                 headers={"content-type": "application/json"})
    return json.loads(urllib.request.urlopen(req, timeout=30).read() or b"{}")


def enforce(mode="enforce"):
    """off | audit | enforce for the whole space. The root test credentials stay allowed for every service the simulator can map to an IAM action;
    only the IAM users you create are judged. Enforce is switched back off when your script ends, so the other chapters keep working
    (a production account would leave it on and map every service)."""
    if mode != "off":
        atexit.register(lambda: _admin("PUT", "/api/iam/aws/enforcement", {"space": "off"}))
    return _admin("PUT", "/api/iam/aws/enforcement", {"space": mode})


def allow(actions, resources="*"):
    return {"Effect": "Allow", "Action": actions if isinstance(actions, list) else [actions], "Resource": resources}


def _put(p):
    boto3.client("iam").put_user_policy(UserName=p["name"], PolicyName=p["name"] + "-least-privilege",
                                        PolicyDocument=json.dumps({"Version": "2012-10-17", "Statement": p["statements"]}))


def principal(name, statements):
    """Create (or reset) IAM user `name` with ONE inline policy and return it with fresh access keys."""
    iam = boto3.client("iam")
    try:
        iam.create_user(UserName=name)
    except iam.exceptions.EntityAlreadyExistsException:
        pass
    for k in iam.list_access_keys(UserName=name)["AccessKeyMetadata"]:
        iam.delete_access_key(UserName=name, AccessKeyId=k["AccessKeyId"])
    p = {"name": name, "arn": "arn:aws:iam::%s:user/%s" % (ACCOUNT, name), "statements": list(statements)}
    _put(p)
    k = iam.create_access_key(UserName=name)["AccessKey"]
    p.update(key=k["AccessKeyId"], secret=k["SecretAccessKey"])
    return p


def grant(p, statements):
    """Add statements to the principal's policy."""
    p["statements"] = p["statements"] + list(statements)
    _put(p)


def client(service, p, **kw):
    """A boto3 client that signs as principal p."""
    return boto3.client(service, aws_access_key_id=p["key"], aws_secret_access_key=p["secret"], **kw)


def last_audit_id():
    recs = _admin("GET", "/api/iam/aws/audit?limit=1")["records"]
    return recs[0]["id"] if recs else 0


def audit(p, since=0):
    """Every authorization decision the simulator made for principal p after audit id `since`, oldest first."""
    recs = _admin("GET", "/api/iam/aws/audit?limit=500")["records"]
    return sorted([r for r in recs if r["principal"] == p["arn"] and r["id"] > since], key=lambda r: r["id"])


def denied(p, since=0):
    """(action, resource) pairs that were refused: this is what 'find what is missing' reads."""
    return sorted({(r["action"], r["resource"]) for r in audit(p, since) if r["decision"] == "deny"})


def missing_statements(p, since=0):
    """One Allow statement per refused (action, resource): the narrowest fix the audit log can justify."""
    return [allow(a, r) for a, r in denied(p, since)]


def settle(p, run, max_rounds=8):
    """Run `run()` as principal p. While it is refused, read the audit log, grant exactly what it names and run again.
    Returns the statements that had to be added: if you wrote the policy right this is empty."""
    added = []
    for _ in range(max_rounds):
        since = last_audit_id()
        try:
            run()
            return added
        except Exception as e:
            code = getattr(e, "response", {}).get("Error", {}).get("Code", "")
            if code not in ("AccessDenied", "AccessDeniedException", "UnauthorizedOperation", "403") and "403" not in str(e):
                raise
            fix = missing_statements(p, since)
            assert fix, "refused but the audit log names nothing: %s" % e
            grant(p, fix)
            added += fix
    raise AssertionError("policy still incomplete after %d rounds: %s" % (max_rounds, added))

import json
import os
import re
import time
import uuid
from typing import TypedDict

import boto3
from langgraph.graph import END, StateGraph

import mcp_client

from vymodels import CHAT_MODEL as MODEL_ID
LAMBDAS = {"kb_search": "facilities-kb-search", "asset_status": "facilities-asset-status"}
GATEWAY = {}


class S(TypedDict, total=False):
    question: str
    user: str
    route: list
    facts: list
    citations: list
    analytics: dict
    approval: dict
    answer: str
    llm_used: bool
    tools: list
    spans: list
    steps: int
    stopped: str


def guarded(fn):
    """Step budget and kill switch: every agent node counts as a step, and over budget the graph stops cleanly instead of running on.
    The limit belongs to the runtime (an environment variable), not to the caller, so a user cannot raise it."""
    def run(st):
        limit = int(os.environ.get("AGENT_MAX_STEPS", "12"))
        if st.get("stopped"):
            return st
        st["steps"] = st.get("steps", 0) + 1
        if st["steps"] > limit:
            st["stopped"] = "step_budget"
            st["answer"] = "I stopped because this request needed more than %d steps." % limit
            return st
        return fn(st)
    return run


def converse(system, text, max_tokens=300):
    try:
        r = boto3.client("bedrock-runtime").converse(modelId=MODEL_ID, system=[{"text": system}],
                                                     messages=[{"role": "user", "content": [{"text": text}]}],
                                                     inferenceConfig={"maxTokens": max_tokens, "temperature": 0})
        return r["output"]["message"]["content"][0]["text"]
    except Exception:
        return None


def discover_gateway():
    """Use the AgentCore Gateway when it exists and serves both tools."""
    GATEWAY.clear()
    try:
        gws = boto3.client("bedrock-agentcore-control").list_gateways()["items"]
        gw = next(g for g in gws if g["name"] == "facilities-gateway")
        names = {t["name"] for t in mcp_client.call(gw["gatewayId"], "tools/list")["tools"]}
        if any("kb_search" in n for n in names) and any("asset_status" in n for n in names):
            GATEWAY.update(id=gw["gatewayId"], tools=names)
    except Exception:
        pass


def call_tool(tool, args, st):
    t0 = time.time()
    try:
        if GATEWAY:
            name = [n for n in GATEWAY["tools"] if tool in n][0]
            res = mcp_client.call(GATEWAY["id"], "tools/call", {"name": name, "arguments": args})
            out, via = (json.loads(res["content"][0]["text"]) if res.get("content") else res), "agentcore-gateway"
        else:
            r = boto3.client("lambda").invoke(FunctionName=LAMBDAS[tool], Payload=json.dumps(args).encode())
            out, via = json.loads(r["Payload"].read() or b"null"), "lambda-direct"
            if "FunctionError" in r:
                raise RuntimeError(str(out)[:120])
    except Exception as e:
        out, via = {"error": type(e).__name__ + ": " + str(e)[:100]}, "unavailable"
    st.setdefault("tools", []).append({"tool": tool, "via": via, "args": args})
    st.setdefault("spans", []).append(dict(name="tool:" + tool, kind="tool", start=t0, end=time.time(), via=via))
    return out


def start_approval(rid, payload):
    sf = boto3.client("stepfunctions")
    try:
        sm = next(m for m in sf.list_state_machines()["stateMachines"] if m["name"] == "work-order-approval")
        ex = sf.start_execution(stateMachineArn=sm["stateMachineArn"], name=rid, input=json.dumps(payload))
        return {"request_id": rid, "execution_arn": ex["executionArn"], "status": "PENDING_APPROVAL"}
    except Exception as e:
        return {"request_id": rid, "status": "APPROVAL_UNAVAILABLE", "error": type(e).__name__}


ROUTER_PROMPT = (
    "You route facilities requests to specialist agents. The agents are:\n"
    "- facilities: searches the knowledge base (SOPs, safety rules, policies, procedures).\n"
    "- maintenance: looks up a specific asset (ids like B-12 or AHU-7) and its work orders, and can raise a work order.\n"
    "- analytics: counts and statistics over work orders.\n"
    "Reply with only a JSON list such as [\"facilities\",\"maintenance\"], drawn from [\"facilities\",\"maintenance\",\"analytics\"].")
ANALYTICS_ONLY = re.compile(r"^\s*(how many|count|give me a summary|summary of|report|trend)", re.I)


def build():
    def span(st, name, t0):
        st.setdefault("spans", []).append(dict(name=name, kind="agent", start=t0, end=time.time()))

    def supervisor(st):
        t0 = time.time()
        plan, txt = None, converse(ROUTER_PROMPT, st["question"], 60)
        if txt:
            try:
                plan = [p for p in json.loads(re.search(r"\[.*\]", txt, re.S).group(0)) if p in ("facilities", "maintenance", "analytics")]
            except Exception:
                plan = None
        st["llm_used"] = bool(plan)
        if plan and "facilities" not in plan and not ANALYTICS_ONLY.search(st["question"]):
            plan.insert(0, "facilities")      # grounding rule: every non-statistics question is answered from the knowledge base
        if not plan:                          # no model reachable: keyword routing
            plan = ["facilities"]
            if re.search(r"[A-Z]{1,3}-\d+|work order|status|ticket|asset", st["question"]):
                plan.append("maintenance")
            if re.search(r"how many|count|summary|report|trend|open work orders", st["question"].lower()):
                plan.append("analytics")
        st["route"] = plan
        span(st, "supervisor.plan", t0)
        return st

    def facilities(st):
        t0 = time.time()
        out = call_tool("kb_search", {"query": st["question"], "top_k": 3}, st)
        results = out.get("results", [])
        st["facts"] = [r["text"] for r in results]
        st["citations"] = [{"n": i + 1, "source": r["source"], "text": r["text"][:160]} for i, r in enumerate(results)]
        span(st, "agent:facilities", t0)
        return st

    def maintenance(st):
        t0 = time.time()
        m = re.search(r"\b([A-Z]{1,3}-\d+)\b", st["question"])
        if m:
            out = call_tool("asset_status", {"asset_id": m.group(1)}, st)
            if out.get("found"):
                open_wos = [w["work_order_id"] + " " + w["title"] for w in out["work_orders"] if w.get("status") == "OPEN"]
                st.setdefault("facts", []).append("Asset %s status %s; open work orders: %s." % (m.group(1), out["asset"].get("status"), open_wos or "none"))
                if re.search(r"work order|raise|open a|create", st["question"], re.I):      # write path: human approval first
                    rid = "req-" + uuid.uuid4().hex[:10]
                    st["approval"] = start_approval(rid, {
                        "request_id": rid, "asset_id": m.group(1), "summary": "Work order for %s: %s" % (m.group(1), st["question"][:100]),
                        "priority": "P1" if re.search(r"exceed|pressure|fire|trapped", st["question"], re.I) else "P2", "requester": st.get("user", "")})
                    st["tools"].append({"tool": "create_work_order", "via": "step-functions-approval", "args": {"request_id": rid}})
        span(st, "agent:maintenance", t0)
        return st

    def analytics(st):
        t0 = time.time()
        try:
            items = boto3.client("dynamodb").scan(TableName="facilities-work-orders")["Items"]
            rows = [{k: list(v.values())[0] for k, v in i.items()} for i in items]
        except Exception:
            rows = None
        if rows is None:
            st["analytics"] = {"error": "work-order table not available yet"}
        else:
            by = {}
            for w in rows:
                by.setdefault(w["status"], {}).setdefault(w["priority"], 0)
                by[w["status"]][w["priority"]] += 1
            st["analytics"] = {"total": len(rows), "by_status_priority": by}
            st.setdefault("facts", []).append("Work orders: %d total; by status/priority %s." % (len(rows), json.dumps(by)))
        st.setdefault("tools", []).append({"tool": "work_order_stats", "via": "dynamodb" if rows is not None else "unavailable", "args": {}})
        span(st, "agent:analytics", t0)
        return st

    def synth(st):
        t0 = time.time()
        cites = st.get("citations", [])
        ctxt = "\n".join("[%d] %s" % (c["n"], c["text"]) for c in cites) + "\n" + "\n".join(st.get("facts", [])[len(cites):])
        txt = converse("Answer using only the context. Cite sources like [1].", "Context:\n%s\n\nQuestion: %s" % (ctxt, st["question"]), 300)
        if txt:
            st["answer"] = txt
        else:
            parts = []
            if cites:
                first = cites[0]["text"].split("\n")
                parts.append("%s: %s [1]" % (first[0].lstrip("# ").strip(), " ".join(first[1:]).strip()))
            parts += st.get("facts", [])[len(cites):]
            if st.get("approval", {}).get("status") == "PENDING_APPROVAL":
                parts.append("A work order request (%s) was submitted and is waiting for approval." % st["approval"]["request_id"])
            st["answer"] = " ".join(parts) or "I could not reach my tools yet, so I have nothing grounded to answer with."
        span(st, "supervisor.synthesize", t0)
        return st

    g = StateGraph(S)
    for n, f in [("supervisor", supervisor), ("facilities", facilities), ("maintenance", maintenance), ("analytics", analytics), ("synth", synth)]:
        g.add_node(n, guarded(f))
    g.set_entry_point("supervisor")

    def nxt(after):
        order = ["facilities", "maintenance", "analytics"]

        def r(st):
            rest = [a for a in order[order.index(after) + 1:] if a in st["route"]] if after else [a for a in order if a in st["route"]]
            return rest[0] if rest else "synth"
        return r
    for n in (None, "facilities", "maintenance", "analytics"):
        g.add_conditional_edges(n or "supervisor", nxt(n), {"facilities": "facilities", "maintenance": "maintenance", "analytics": "analytics", "synth": "synth"})
    g.add_edge("synth", END)
    return g.compile()


def ask(question, user="anonymous"):
    discover_gateway()
    return build().invoke({"question": question, "user": user, "tools": [], "spans": []})

